  const published=(data?.activities||[]).reduce((n,a)=>n+a.entries.filter(r=>r.published).length,0),follow=followUps();
  root.innerHTML=`<section class="gradebook ${compact?'gradebook-compact':''}"><div class="gb-heading"><div><p class="assessment-eyebrow">EVIDENCE → FEEDBACK → NEXT STEP</p><h2>Gradebook</h2><p>Teacher-published grades are official. Automatic / AI results stay labelled evidence.</p></div>${button('+ Record an activity','data-gb-create',false)}</div><div class="gb-toolbar"><div class="gb-toggle" role="group" aria-label="Assessment source">${[['automatic','Automatic / AI'],['teacher','Teacher'],['both','Both']].map(([id,label])=>`<button type="button" data-gb-source="${id}" aria-pressed="${source===id}">${label}</button>`).join('')}</div><span>${published} published result${published===1?'':'s'} · ${follow.length} follow-up${follow.length===1?'':'s'}</span>${button('Refresh','data-gb-refresh')}</div><p data-gb-status role="status"></p><div class="gb-layout"><aside class="gb-activities" aria-label="Assessment activities"><h3>Activities</h3>${(data?.activities||[]).filter(a=>!a.reporting).map(item=>`<button type="button" data-gb-activity="${e(item.id)}" aria-pressed="${selected===item.id}"><strong>${e(item.title)}</strong><small>${e(item.date)} · ${e(item.purpose)}</small><span>${item.entries.filter(r=>r.published).length} published · ${item.entries.filter(r=>r.draft&&r.draft.at!==r.published?.at).length} drafts</span></button>`).join('')}${quizLessons.filter(l=>!data?.activities.some(a=>a.source.kind==='quiz'&&a.source.id===l.id)).map(l=>`<button type="button" data-gb-activity="quiz:${e(l.id)}" aria-pressed="${selected==='quiz:'+l.id}"><strong>${e(l.quiz.title)}</strong><small>Automatic quiz evidence</small></button>`).join('')||''}${!data?.activities.length&&!quizLessons.length?'<p>No activities yet. Record a lesson, notebook task, observation or paper assessment.</p>':''}</aside><section class="gb-selected">${a||quiz?`<div class="gb-heading"><div><h3>${e(a?.title||quiz.title)}</h3><p>${a?e(a.date)+' · '+e(a.purpose):'Automatically marked quiz'}${a?.source.kind!=='manual'&&a?' · Linked '+e(a.source.kind):''}</p></div>${onlyAutomatic?button('Assess this quiz','data-gb-from-quiz',false):button('Edit activity','data-gb-edit')}</div>${a?.successCriteria?`<p><strong>Success criteria:</strong> ${e(a.successCriteria)}</p>`:''}${a?.standards.length?`<details class="gb-targets" open><summary>Learning targets & standards</summary>${a.standards.map(s=>`<p><strong>${e(s.code)}</strong> ${e(s.title)}</p>`).join('')}</details>`:''}<div class="gb-roster-tools"><label>Find a student<input type="search" data-gb-search value="${e(query)}" placeholder="Student name"></label><label><input type="checkbox" data-gb-follow ${followOnly?'checked':''}> Follow-up needed</label></div><div class="gb-table-scroll"><table class="gb-table"><thead><tr><th scope="col">Student</th>${source!=='teacher'?'<th scope="col">Automatic / AI · evidence</th>':''}${source!=='automatic'?'<th scope="col">Teacher · official / draft</th>':''}</tr></thead><tbody>${people.map(s=>{const row=rowFor(a,s.id),entry=row?.draft||row?.published;return `<tr><th scope="row">${e(s.name)}</th>${source!=='teacher'?`<td>${quiz?autoHTML(autoFor(quiz,s.id)):'<span class="gb-muted">No automatic assessment linked</span>'}</td>`:''}${source!=='automatic'?`<td>${row?.published?`<span class="gb-badge">Published · official</span><strong>${e(gradeLabel(row.published,row.published.activity))}</strong>${(row.published.judgments||[]).map(j=>`<small>${e(j.code)} · ${e(standardsLevels[j.level])}</small>`).join('')}`:'<span class="gb-muted">No published teacher result</span>'}${row?.draft&&row.draft.at!==row.published?.at?`<span class="gb-badge gb-draft">Private draft</span><span>${e(gradeLabel(row.draft,a))}</span>`:''}${entry?.followUp&&!entry.followUpDone?`<small>Recheck ${e(entry.followUp)}</small>`:''}${a?button('Record / review',`data-gb-student="${e(s.id)}"`):'<small>Choose “Assess this quiz” to add a teacher judgment.</small>'}</td>`:''}</tr>`;}).join('')||`<tr><td colspan="3">No students match this view.</td></tr>`}</tbody></table></div>${source!=='teacher'?'<p class="gb-note">Quiz results are automatically marked, not AI judgments. First, latest and best attempts remain separate. No automatic result is averaged into a teacher grade.</p>':''}`:'<div class="assessment-empty"><h3>Start with a learning target</h3><p>Record evidence from any activity. A score is optional for formative assessment.</p></div>'}</section></div>${source!=='automatic'?`<details class="gb-followups" ${follow.length?'open':''}><summary>Teaching follow-up queue · ${follow.length}</summary>${follow.map(({a,r,entry})=>`<button type="button" data-gb-recheck="${e(a.id)}" data-learner="${e(r.learnerId)}"><strong>${e(students.find(s=>s.id===r.learnerId)?.name||'Student')}</strong><span>${e(a.title)} · ${e(entry.followUp)}</span><small>${e(entry.nextStep||'Recheck the learning target')}</small></button>`).join('')||'<p>No rechecks scheduled. Add a next step and recheck date when recording evidence.</p>'}</details>${liveBoardEvidenceHTML(boardEvidence,{classId,students,learnerId,unavailable:boardEvidenceUnavailable})}${lessons.some(l=>l.report?.assessments?.length)?`<details class="gb-existing"><summary>Published lesson feedback · teacher evidence</summary><p>Effort, preparedness and attitude are recorded separately from academic achievement.</p>${lessons.filter(l=>l.report?.assessments?.length).map(l=>`<p><a href="/teacher?view=classes&amp;class=${e(classId)}&amp;tab=timeline">${e(l.title)}</a> · ${l.report.assessments.length} student reports</p>`).join('')}</details>`:''}`:''}</section>`;
  root.querySelectorAll('[data-gb-source]').forEach(b=>b.onclick=()=>{source=b.dataset.gbSource;onSource(source);render();root.querySelector(`[data-gb-source="${source}"]`)?.focus();});
