 root.innerHTML='<p data-gb-status role="status">Loading learning evidence…</p>';if(initialData){selected=data.activities.find(a=>!a.reporting)?.id||(quizLessons[0]?'quiz:'+quizLessons[0].id:'');render();ready();const wanted=new URLSearchParams(location.search).get('activitySource');if(wanted){entryHandled=true;const existing=data.activities.find(a=>a.source.kind+':'+a.source.id===wanted);if(existing){selected=existing.id;render();const person=new URLSearchParams(location.search).get('gradeLearner');if(person)review(person);}else create(null,wanted);}}else load();
 return {async createActivityForStandard(standard,person=''){await readyPromise;if(!closed)await create(null,'',null,standard,person);},async openRecord(id,person){await readyPromise;if(closed||!data.activities.some(a=>a.id===id))return;selected=id;render();await review(person);},clear(){closed=true;dialog?.close();root.replaceChildren();}};
