export async function renderPublishedGrades(root,classId,{learnerId='',parent=false}={}){
 root.textContent='Loading teacher-published grades…';
 try{const data=await api('/api/gradebook/classes/'+encodeURIComponent(classId));if(!root.isConnected)return;const rows=data.activities.flatMap(a=>a.entries.filter(r=>!learnerId||r.learnerId===learnerId).map(r=>({id:a.id,...r}))).sort((a,b)=>b.published.at-a.published.at);
  root.innerHTML=`<section class="gb-family"><h2>Teacher-published grades & next steps</h2><p>Official results published by your teacher. Quiz scores elsewhere are labelled automatic evidence.</p>${rows.length?rows.map(r=>{const p=r.published;return `<article><small>${parent?e(data.students.find(s=>s.id===r.learnerId)?.name)+' · ':''}${e(p.activity.date)} · ${e(p.activity.purpose)}</small><h3>${e(p.activity.title)}</h3><strong>${e(gradeLabel(p,p.activity))}</strong>${p.judgments?.length?`<ul>${p.judgments.map(j=>`<li>${e(j.code)}: ${e(standardsLevels[j.level])}</li>`).join('')}</ul>`:''}${p.evidenceNote?`<p>${e(p.evidenceNote)}</p>`:''}${p.feedback?`<p><strong>Feedback:</strong> ${e(p.feedback)}</p>`:''}${p.nextStep?`<p><strong>Next step:</strong> ${e(p.nextStep)}</p>`:''}<small>Published ${e(date(p.at))}</small></article>`;}).join(''):'<p>No teacher-published grades yet.</p>'}</section>`;
 }catch(err){root.textContent='Teacher grades: '+err.message;}
}
